"""The centrepiece: speech generated by one model is understood by another, through the API.

If sample rates, dtypes, resampling or encoding are wrong anywhere in the stack, the word error
rate here goes through the roof. No unit test can catch that — every one of them mocks at least
one end of this path.
"""

from __future__ import annotations

import re

import pytest

from tests.e2e.audio import REFERENCE_TEXT, speech_wav, wer

pytestmark = pytest.mark.e2e


def _post(admin, wav, **data):
    return admin.post(
        "/v1/audio/transcriptions",
        files={"file": ("speech.wav", wav.read_bytes(), "audio/wav")},
        data=data,
    )


def test_tts_to_stt_round_trip(admin):
    wav = speech_wav(REFERENCE_TEXT)
    r = _post(admin, wav)
    assert r.status_code == 200, r.text
    text = r.json()["text"]
    error = wer(REFERENCE_TEXT, text)
    assert error <= 0.2, f"WER {error:.2f}\n  said:  {REFERENCE_TEXT}\n  heard: {text}"


def test_verbose_json_has_ordered_segments_and_word_timestamps(admin):
    wav = speech_wav(REFERENCE_TEXT)
    r = _post(admin, wav, response_format="verbose_json", **{"timestamp_granularities[]": "word"})
    assert r.status_code == 200, r.text
    body = r.json()
    assert body["language"] and body["duration"] > 0
    assert body["segments"], "no segments"
    for seg in body["segments"]:
        assert seg["start"] <= seg["end"]

    # `words` is a flat top-level list, as OpenAI's verbose_json has it — not nested per segment.
    words = body["words"]
    assert words, "word timestamps were requested but none came back"
    starts = [w["start"] for w in words]
    assert starts == sorted(starts), "word timestamps are not monotonic"
    assert words[-1]["end"] <= body["duration"] + 0.5
    assert all(w["word"].strip() for w in words)


def test_word_timestamps_are_omitted_unless_asked_for(admin):
    wav = speech_wav(REFERENCE_TEXT)
    body = _post(admin, wav, response_format="verbose_json").json()
    assert "words" not in body


@pytest.mark.parametrize("fmt", ["json", "verbose_json", "text", "srt", "vtt"])
def test_every_response_format_renders(admin, fmt):
    wav = speech_wav(REFERENCE_TEXT)
    r = _post(admin, wav, response_format=fmt)
    assert r.status_code == 200, r.text
    if fmt in ("json", "verbose_json"):
        assert r.json()["text"].strip()
    else:
        assert r.text.strip()


def test_srt_and_vtt_are_well_formed_cues(admin):
    wav = speech_wav(REFERENCE_TEXT)
    srt = _post(admin, wav, response_format="srt").text
    # "1\n00:00:00,000 --> 00:00:03,120\ntext"
    assert re.search(r"^1\r?\n\d{2}:\d{2}:\d{2},\d{3} --> \d{2}:\d{2}:\d{2},\d{3}", srt)

    vtt = _post(admin, wav, response_format="vtt").text
    assert vtt.startswith("WEBVTT")
    assert re.search(r"\d{2}:\d{2}:\d{2}\.\d{3} --> \d{2}:\d{2}:\d{2}\.\d{3}", vtt)


def test_an_unknown_response_format_is_rejected(admin):
    wav = speech_wav(REFERENCE_TEXT)
    r = _post(admin, wav, response_format="yaml")
    assert r.status_code == 422
    assert "response_format" in r.json()["error"]["message"]


def test_model_selection_is_allowlisted(admin):
    wav = speech_wav("Testing the model allowlist.")
    assert _post(admin, wav, model="not-a-model").status_code == 422

    catalogue = admin.get("/v1/audio/models").json()
    assert catalogue["default"] == "small.en"
    other = next(m for m in catalogue["models"] if m["id"] != "small.en" and "tiny" in m["id"])
    r = _post(admin, wav, model=other["id"])  # decodes on its own cached instance
    assert r.status_code == 200 and r.json()["text"].strip()

    # OpenAI's alias resolves to the configured default rather than being rejected.
    assert _post(admin, wav, model="whisper-1").status_code == 200


def test_a_non_audio_upload_is_rejected_without_leaking_paths(admin):
    r = admin.post(
        "/v1/audio/transcriptions",
        files={"file": ("notes.txt", b"this is not audio at all", "text/plain")},
    )
    assert r.status_code == 400
    message = r.json()["error"]["message"]
    assert message == "could not decode uploaded audio"
    assert "/" not in message and "ffmpeg" not in message.lower()
